function SpawnDecal(part,side)
	local args = {
		[1] = "CreateTextures",
		[2] = {
			[1] = {
				["Part"] = part,
				["Face"] = side,
				["TextureType"] = "Decal"
			}
		}
	}
	_(args)
end

function AddDecal(part,asset,side)
	local args = {
		[1] = "SyncTexture",
		[2] = {
			[1] = {
				["Part"] = part,
				["Face"] = side,
				["TextureType"] = "Decal",
				["Texture"] = "rbxassetid://".. asset
			}
		}
	}
	_(args)
end

function Sky(id)
	local root = char:WaitForChild("HumanoidRootPart")
	local pos = root.CFrame + Vector3.new(0, 6, 0)
	CreatePart(pos, workspace)
	task.wait(0.2)
	local skyPart
	for _, v in workspace:GetChildren() do
		if v:IsA("BasePart") and (v.Position - pos.Position).magnitude < 1 then
			skyPart = v
			break
		end
	end
	if skyPart then
		SetName(skyPart, "Sky")
		AddMesh(skyPart)
		SetMesh(skyPart, "111891702759441")
		SetTexture(skyPart, id)
		MeshResize(skyPart, Vector3.new(1000, 1000, 1000))
		SetLocked(skyPart, true)
		SetAnchor(true, skyPart)
	end
end

Sky("put your own texture id here")

